<template><div v-loading="loading"><el-tabs v-model="tab" @tab-click="tabChanged"><el-tab-pane label="账号与权限" name="users"><section class="card"><div class="card-heading"><div><h2>岗位账号</h2><p>账号按岗位授权，停用后会立即失去业务访问权限</p></div><el-button type="primary" icon="el-icon-plus" @click="openUser">新增账号</el-button></div><el-table :data="users"><el-table-column prop="username" label="账号"/><el-table-column prop="display_name" label="姓名"/><el-table-column label="岗位"><template slot-scope="s">{{label(s.row.role_code)}}</template></el-table-column><el-table-column prop="department_name" label="所属科室"/><el-table-column label="状态" width="100"><template slot-scope="s"><span class="status" :class="s.row.active?'green':'gray'">{{s.row.active?'已启用':'已停用'}}</span></template></el-table-column><el-table-column label="操作" width="100"><template slot-scope="s"><el-button type="text" :disabled="s.row.id===user.id" @click="toggleUser(s.row)">{{s.row.active?'停用':'启用'}}</el-button></template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane label="医生排班" name="schedules"><section class="card"><div class="card-heading"><div><h2>排班与号源</h2><p>上午、下午独立限额；现场挂号仅接受当天排班</p></div><el-button type="primary" icon="el-icon-plus" @click="scheduleDialog=true">新增排班</el-button></div><div class="toolbar"><el-date-picker v-model="range" type="daterange" value-format="yyyy-MM-dd" start-placeholder="开始日期" end-placeholder="结束日期"/><el-button @click="loadSchedules">查询</el-button></div><el-table :data="schedules"><el-table-column prop="visit_date" label="出诊日期" width="120"/><el-table-column prop="period" label="时段" width="70"/><el-table-column prop="doctor_name" label="医生"/><el-table-column prop="department_name" label="科室"/><el-table-column prop="level_name" label="号别"/><el-table-column label="挂号费"><template slot-scope="s">{{money(s.row.fee_cents)}}</template></el-table-column><el-table-column prop="quota" label="限额" width="70"/><el-table-column prop="booked" label="已挂" width="70"/></el-table></section></el-tab-pane>
<el-tab-pane label="科室目录" name="departments"><section class="card"><div class="card-heading"><h2>科室信息</h2><el-button type="primary" @click="departmentDialog=true">新增科室</el-button></div><el-table :data="catalog.departments"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="科室"/><el-table-column label="类别"><template slot-scope="s">{{s.row.kind==='OUTPATIENT'?'门诊':label(s.row.kind)}}</template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane label="项目与药品" name="catalog"><section class="card"><div class="card-heading"><div><h2>医技项目目录</h2><p>改价仅影响新开立医嘱，历史金额保留快照</p></div><el-button type="primary" @click="openItem()">新增项目</el-button></div><el-table :data="catalog.items"><el-table-column prop="code" label="编码" width="90"/><el-table-column prop="name" label="名称"/><el-table-column label="类别" width="70"><template slot-scope="s">{{label(s.row.kind)}}</template></el-table-column><el-table-column prop="specification" label="规格"/><el-table-column label="单价" width="110"><template slot-scope="s">{{money(s.row.price_cents)}}</template></el-table-column><el-table-column label="操作" width="160"><template slot-scope="s"><el-button type="text" @click="openItem(s.row)">编辑</el-button><el-button type="text" @click="toggleCatalog('item',s.row)">{{s.row.active?'停用':'启用'}}</el-button></template></el-table-column></el-table></section><section class="card section-gap"><div class="card-heading"><h2>药品目录</h2><el-button type="primary" @click="openMedicine()">新增药品</el-button></div><el-table :data="catalog.medicines"><el-table-column prop="code" label="编码" width="90"/><el-table-column prop="name" label="名称"/><el-table-column prop="unit" label="单位" width="70"/><el-table-column prop="manufacturer" label="厂家"/><el-table-column label="单价" width="110"><template slot-scope="s">{{money(s.row.price_cents)}}</template></el-table-column><el-table-column label="操作" width="160"><template slot-scope="s"><el-button type="text" @click="openMedicine(s.row)">编辑</el-button><el-button type="text" @click="toggleCatalog('medicine',s.row)">{{s.row.active?'停用':'启用'}}</el-button></template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane label="操作审计" name="audit"><section class="card"><div class="card-heading"><div><h2>操作审计记录</h2><p>业务修改与患者资料访问均保留操作记录</p></div><el-button icon="el-icon-refresh" @click="loadAudit">刷新</el-button></div><el-table :data="logs.items"><el-table-column prop="actor_name" label="操作人" width="100"/><el-table-column prop="action_name" label="操作" width="190"/><el-table-column prop="entity_id" label="关联记录" min-width="200" show-overflow-tooltip/><el-table-column prop="detail" label="说明" min-width="170"/><el-table-column label="时间" min-width="170"><template slot-scope="s">{{date(s.row.created_at)}}</template></el-table-column></el-table><el-pagination :current-page.sync="auditPage" :page-size="20" :total="logs.total" layout="total,prev,pager,next" @current-change="loadAudit"/></section></el-tab-pane></el-tabs>
<el-dialog title="新增岗位账号" :visible.sync="userDialog" width="560px"><el-form label-position="top" class="form-grid"><el-form-item label="登录账号（字母开头，3至40位）"><el-input v-model="newUser.username" maxlength="40"/></el-form-item><el-form-item label="姓名"><el-input v-model="newUser.display_name" maxlength="60"/></el-form-item><el-form-item label="岗位"><el-select v-model="newUser.role_code" @change="newUser.department_id='' "><el-option v-for="r in roles" :key="r" :value="r" :label="label(r)"/></el-select></el-form-item><el-form-item label="所属科室"><el-select v-model="newUser.department_id" clearable><el-option v-for="d in userDepartments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="初始密码（至少10位）" class="full"><el-input v-model="newUser.password" type="password" show-password maxlength="64"/></el-form-item></el-form><span slot="footer"><el-button @click="userDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveUser">创建账号</el-button></span></el-dialog>
<el-dialog title="新增医生排班" :visible.sync="scheduleDialog" width="560px"><el-form label-position="top" class="form-grid"><el-form-item label="门诊医生"><el-select v-model="schedule.doctor_id"><el-option v-for="u in catalog.staff.filter(u=>u.role_code==='DOCTOR')" :key="u.id" :value="u.id" :label="`${u.display_name} · ${u.department_name}`"/></el-select></el-form-item><el-form-item label="出诊日期"><el-date-picker v-model="schedule.visit_date" type="date" value-format="yyyy-MM-dd"/></el-form-item><el-form-item label="时段"><el-select v-model="schedule.period"><el-option value="上午"/><el-option value="下午"/></el-select></el-form-item><el-form-item label="号别"><el-input v-model="schedule.level_name" maxlength="20"/></el-form-item><el-form-item label="挂号费（元）"><el-input-number v-model="schedule.fee" :min="0" :precision="2"/></el-form-item><el-form-item label="挂号限额"><el-input-number v-model="schedule.quota" :min="1" :max="1000"/></el-form-item></el-form><span slot="footer"><el-button @click="scheduleDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveSchedule">保存排班</el-button></span></el-dialog>
<el-dialog title="新增科室" :visible.sync="departmentDialog" width="460px"><el-form label-position="top"><el-form-item label="科室编码"><el-input v-model="department.code" maxlength="32"/></el-form-item><el-form-item label="科室名称"><el-input v-model="department.name" maxlength="80"/></el-form-item><el-form-item label="科室类型"><el-select v-model="department.kind"><el-option value="OUTPATIENT" label="门诊"/><el-option v-for="k in ['CHECK','LAB','TREAT','PHARMACY']" :key="k" :value="k" :label="label(k)"/></el-select></el-form-item></el-form><span slot="footer"><el-button @click="departmentDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveDepartment">保存科室</el-button></span></el-dialog>
<el-dialog :title="editId?'编辑医技项目':'新增医技项目'" :visible.sync="itemDialog" width="560px"><el-form label-position="top" class="form-grid"><el-form-item label="项目编码"><el-input v-model="item.code" maxlength="32"/></el-form-item><el-form-item label="项目名称"><el-input v-model="item.name" maxlength="100"/></el-form-item><el-form-item label="项目类别"><el-select v-model="item.kind" @change="item.department_id=''"><el-option v-for="k in ['CHECK','LAB','TREAT']" :key="k" :value="k" :label="label(k)"/></el-select></el-form-item><el-form-item label="执行科室"><el-select v-model="item.department_id"><el-option v-for="d in catalog.departments.filter(d=>d.kind===item.kind)" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="规格"><el-input v-model="item.specification" maxlength="100"/></el-form-item><el-form-item label="单价（元）"><el-input-number v-model="item.price" :min="0.01" :precision="2"/></el-form-item></el-form><span slot="footer"><el-button @click="itemDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveItem">保存项目</el-button></span></el-dialog>
<el-dialog :title="editId?'编辑药品':'新增药品'" :visible.sync="medicineDialog" width="560px"><el-form label-position="top" class="form-grid"><el-form-item label="药品编码"><el-input v-model="medicine.code" maxlength="32"/></el-form-item><el-form-item label="药品名称"><el-input v-model="medicine.name" maxlength="100"/></el-form-item><el-form-item label="拼音助记码"><el-input v-model="medicine.pinyin" maxlength="80"/></el-form-item><el-form-item label="包装单位"><el-input v-model="medicine.unit" maxlength="20"/></el-form-item><el-form-item label="生产厂家"><el-input v-model="medicine.manufacturer" maxlength="120"/></el-form-item><el-form-item label="剂型"><el-input v-model="medicine.formulation" maxlength="40"/></el-form-item><el-form-item label="单价（元）"><el-input-number v-model="medicine.price" :min="0.01" :precision="2"/></el-form-item></el-form><span slot="footer"><el-button @click="medicineDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveMedicine">保存药品</el-button></span></el-dialog>
</div></template>
<script>import{api,label,money,date,today,cents}from'../api';export default{props:['catalog','user'],data:()=>({loading:false,saving:false,tab:'users',users:[],roles:['ADMIN','CASHIER','DOCTOR','CHECK','LAB','TREAT','PHARMACY'],userDialog:false,newUser:{},scheduleDialog:false,schedule:{doctor_id:'',visit_date:today(),period:'上午',level_name:'普通号',fee:20,quota:30},schedules:[],range:[today(),today()],departmentDialog:false,department:{code:'',name:'',kind:'OUTPATIENT'},itemDialog:false,item:{},medicineDialog:false,medicine:{},editId:null,logs:{items:[],total:0},auditPage:1}),computed:{userDepartments(){const role=this.newUser.role_code;if(role==='DOCTOR')return this.catalog.departments.filter(d=>d.kind==='OUTPATIENT');if(['CHECK','LAB','TREAT'].includes(role))return this.catalog.departments.filter(d=>d.kind===role);return this.catalog.departments;}},created(){this.loadUsers();},methods:{label,money,date,tabChanged(){if(this.tab==='schedules')this.loadSchedules();if(this.tab==='audit')this.loadAudit();},async loadUsers(){this.loading=true;try{this.users=await api.get('/admin/users');}catch{}finally{this.loading=false;}},openUser(){this.newUser={username:'',display_name:'',role_code:'CASHIER',department_id:'',password:''};this.userDialog=true;},async saveUser(){this.saving=true;try{await api.post('/admin/users',this.newUser);this.newUser.password='';this.userDialog=false;this.$message.success('岗位账号已创建');await this.loadUsers();this.$emit('catalog-change');}catch{}finally{this.saving=false;}},async toggleUser(u){try{await this.$confirm(`确认${u.active?'停用':'启用'} ${u.display_name}？`,'账号状态');await api.put(`/admin/users/${u.id}/active`,{active:!u.active});await this.loadUsers();this.$emit('catalog-change');}catch{}},async loadSchedules(){try{this.schedules=await api.get('/schedules',{params:{start:this.range?.[0]||today(),end:this.range?.[1]||today()}});}catch{}},async saveSchedule(){this.saving=true;try{await api.post('/admin/schedules',{...this.schedule,fee_cents:cents(this.schedule.fee)});this.scheduleDialog=false;this.$message.success('排班已创建');await this.loadSchedules();}catch{}finally{this.saving=false;}},async saveDepartment(){this.saving=true;try{await api.post('/admin/departments',this.department);this.departmentDialog=false;this.department={code:'',name:'',kind:'OUTPATIENT'};this.$emit('catalog-change');this.$message.success('科室已创建');}catch{}finally{this.saving=false;}},openItem(row){this.editId=row?.id||null;this.item=row?{...row,price:Number(row.price_cents)/100}:{code:'',name:'',kind:'CHECK',specification:'',department_id:'',price:1};this.itemDialog=true;},async saveItem(){this.saving=true;try{await api[this.editId?'put':'post'](`/admin/items${this.editId?'/'+this.editId:''}`,{...this.item,price_cents:cents(this.item.price)});this.itemDialog=false;this.$emit('catalog-change');this.$message.success('项目已保存');}catch{}finally{this.saving=false;}},openMedicine(row){this.editId=row?.id||null;this.medicine=row?{...row,price:Number(row.price_cents)/100}:{code:'',name:'',pinyin:'',unit:'盒',manufacturer:'',formulation:'',price:1};this.medicineDialog=true;},async saveMedicine(){this.saving=true;try{await api[this.editId?'put':'post'](`/admin/medicines${this.editId?'/'+this.editId:''}`,{...this.medicine,price_cents:cents(this.medicine.price)});this.medicineDialog=false;this.$emit('catalog-change');this.$message.success('药品已保存');}catch{}finally{this.saving=false;}},async toggleCatalog(kind,row){try{await api.put(`/admin/catalog/${kind}/${row.id}/active`,{active:!row.active});this.$emit('catalog-change');}catch{}},async loadAudit(){try{this.logs=await api.get('/admin/audit',{params:{page:this.auditPage}});}catch{}}}};</script>
